int Prior(char op)
{
    if (op == '*' || op == '/') return 2;
    if (op == '+' || op == '-') return 1;
    return 0;
}
/* 把中缀表达式 e 转换成后缀表达式，存入 post */
void Convert(char e[], char post[])
{
    char st[100], c;
    int top = -1, i, k = 0;
    for (i = 0; (c = e[i]) != '\0'; i++) {
        if (c >= 'a' && c <= 'z')
            post[k++] = c;
        else if (c == '(')
            st[++top] = c;
        else if (c == ')') {
            while (st[top] != '(')
                post[k++] = st[top--];
            top--;
        } else {
            while (top != -1 &&
                   Prior(st[top]) >= Prior(c))
                post[k++] = st[top--];
            st[++top] = c;
        }
    }
    while (top != -1)
        post[k++] = st[top--];
    post[k] = '\0';
}
int main(void)
{
    char e[100], post[100];
    scanf("%s", e);
    Convert(e, post);
    printf("%s\n", post);
    return 0;
