typedef struct {
    int data[MAXSIZE];
    int front, rear;
} SqQueue;

int EnQueue(SqQueue *Q, int x)
{
    if ((Q->rear + 1) % MAXSIZE == Q->front)
        return 0;
    Q->data[Q->rear] = x;
    Q->rear = (Q->rear + 1) % MAXSIZE;
    return 1;
}
int DeQueue(SqQueue *Q, int *x)
{
    if (Q->front == Q->rear)
        return 0;
    *x = Q->data[Q->front];
    Q->front = (Q->front + 1) % MAXSIZE;
    return 1;
}
