BiTree Create(void)
{
    BiTree T;
    char ch = getchar();
    if (ch == '#')
        return NULL;
    T = (BiTNode *)malloc(sizeof(BiTNode));
    T->data = ch;
    T->lchild = Create();
    T->rchild = Create();
    return T;
}
int Depth(BiTree T)    /* 求二叉树的高度 */
{
    int hl, hr;
    if (T == NULL) return 0;
    hl = Depth(T->lchild);
    hr = Depth(T->rchild);
    return (hl > hr ? hl : hr) + 1;
}

int Leaf(BiTree T)     /* 求叶子结点个数 */
{
    if (T == NULL) return 0;
    if (!T->lchild && !T->rchild) return 1;
    return Leaf(T->lchild) + Leaf(T->rchild);
}

int main(void)
{
    BiTree T = Create();
    printf("%d %d\n", Depth(T), Leaf(T));
    return 0;
}

