/* 希尔排序：增量 d 依次取 n/2、n/4、…、1，
   每趟结束后输出整个数组 */
void ShellSort(int a[], int n)
{
    int d, i, j, x, k;
    for (d = n / 2; d >= 1; d /= 2) {
        for (i = d; i < n; i++) {
            x = a[i];
            j = i - d;
            while (j >= 0 && a[j] > x) {
                a[j + d] = a[j];
                j -= d;
            }
            a[j + d] = x;
        }
        for (k = 0; k < n; k++)
            printf("%d ", a[k]);
        printf("\n");
    }
}

